//! The place dictionary: the places generated by
//! `just places` into `assets/places/places.csv.br` (see
//! `docs/place-dictionary.md`), searched to suggest place names.
//!
//! The file is decompressed and indexed on the first search, not at startup:
//! it holds about 285,000 rows, and a session that never edits a place never pays
//! for them. Locating a tree's places for the statistics reuses that index
//! when a search has built it, and otherwise reads the file once for the
//! rows named like the tree's places, keeping nothing afterwards
//! ([`locate_places`]).

use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

use serde::Serialize;

use super::loader::{ReferenceLang, normalize_key, starts_a_word};
use crate::embedded;

static PLACES: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../assets/places/places.csv.br"
));

/// Suggestions returned when the caller names no limit.
pub const DEFAULT_PLACE_SUGGESTIONS: usize = 10;
/// The most suggestions one search returns.
pub const MAX_PLACE_SUGGESTIONS: usize = 50;

/// What a dictionary row is. The order is the order suggestions are
/// ranked in when their names match equally well.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum PlaceKind {
    Commune,
    MunicipalArrondissement,
    Settlement,
    Parish,
    FormerName,
    FormerCommune,
}

impl PlaceKind {
    fn parse(token: &str) -> Option<Self> {
        Some(match token {
            "commune" => Self::Commune,
            "municipal_arrondissement" => Self::MunicipalArrondissement,
            "settlement" => Self::Settlement,
            "parish" => Self::Parish,
            "former_name" => Self::FormerName,
            "former_commune" => Self::FormerCommune,
            _ => return None,
        })
    }
}

/// One suggested place, with the parts its label is made of.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct PlaceSuggestion {
    /// The place written the way a genealogy records it: its name, code,
    /// subdivision, region and country, most specific first.
    pub label: String,
    pub name: String,
    /// The INSEE commune code in France.
    pub code: Option<String>,
    pub subdivision: String,
    pub region: String,
    pub country: String,
    pub kind: PlaceKind,
    pub valid_from: Option<String>,
    pub valid_until: Option<String>,
    /// INSEE code of the commune holding a former commune's territory today.
    pub successor: Option<String>,
    pub latitude: Option<f64>,
    pub longitude: Option<f64>,
    /// Filed under today's subdivision and region rather than a former one.
    pub current: bool,
}

/// Searches the place dictionary.
///
/// The text before the first comma is matched against place names: an exact
/// name first, then names starting with it, then names with a word starting
/// with it. Each part after a comma must start a word of the code,
/// subdivision, region or country, so "Name, Subdivision" narrows the list.
/// Case, accents and punctuation are ignored.
pub fn search_places(lang: ReferenceLang, query: &str, limit: usize) -> Vec<PlaceSuggestion> {
    dictionary().search(lang, query, limit)
}

/// Where the place dictionary puts one of a tree's places: its spot, and
/// the country, region and subdivision it lies in, named in the requested
/// language. Any of them may be unknown.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct PlaceLocation {
    pub spot: Option<(f64, f64)>,
    pub country: Option<String>,
    pub region: Option<String>,
    pub subdivision: Option<String>,
}

/// Locates the places of a tree, with how often the tree uses each, in the
/// place dictionary (see `Dictionary::locate_all`).
///
/// The index place searches build is reused when it is in memory. Otherwise
/// the dictionary is decompressed and read once for the rows named like
/// the tree's places (a few thousand of 285,000), and dropped with them:
/// about a quarter of a second in a release build, and nothing held in
/// memory afterwards, where building the whole index would take three
/// times as long and keep a few tens of megabytes for the session.
pub fn locate_places(lang: ReferenceLang, labels: &[(&str, i64)]) -> Vec<PlaceLocation> {
    match DICTIONARY.get() {
        Some(dictionary) => dictionary.locate_all(labels, lang),
        None => Dictionary::for_labels(&decompressed(), labels).locate_all(labels, lang),
    }
}

/// A label read against the dictionary.
enum Located<'a> {
    At(&'a Entry),
    Among(Vec<&'a Entry>),
    Nowhere,
}

fn spot(entry: &Entry) -> (f64, f64) {
    (f64::from(entry.latitude), f64::from(entry.longitude))
}

/// The spot of places all within a fifth of a degree of the first.
fn clustered(entries: &[&Entry]) -> Option<(f64, f64)> {
    let first = spot(entries.first()?);
    entries
        .iter()
        .all(|e| {
            let (latitude, longitude) = spot(e);
            (latitude - first.0).abs() < 0.2 && (longitude - first.1).abs() < 0.2
        })
        .then_some(first)
}

/// Living places before former ones when a bare name is read.
fn kind_rank(kind: PlaceKind) -> u8 {
    match kind {
        PlaceKind::Commune | PlaceKind::MunicipalArrondissement => 0,
        PlaceKind::Settlement | PlaceKind::Parish => 1,
        PlaceKind::FormerCommune | PlaceKind::FormerName => 2,
    }
}

/// The whole dictionary, indexed for place searches on first use and kept.
static DICTIONARY: OnceLock<Dictionary> = OnceLock::new();

fn dictionary() -> &'static Dictionary {
    DICTIONARY.get_or_init(|| Dictionary::parse(&decompressed()))
}

fn decompressed() -> String {
    String::from_utf8(embedded::decompress(PLACES))
        .expect("the embedded place dictionary must be UTF-8")
}

